package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/Shopify/sarama"
	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		// Allow all origins for internal service mesh communication
		return true
	},
}

type StreamEvent struct {
	Action    string `json:"action"`
	Bucket    string `json:"bucket"`
	Key       string `json:"key"`
	Payload   string `json:"payload"`
	Requestor string `json:"requestor"`
}

var s3Client *s3.S3

func init() {
	sess := session.Must(session.NewSession(&aws.Config{
		Region: aws.String(os.Getenv("AWS_REGION")),
	}))
	s3Client = s3.New(sess)
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("WebSocket upgrade failed: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			log.Printf("Read error: %v", err)
			break
		}

		var event StreamEvent
		if err := json.Unmarshal(message, &event); err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid json"}`))
			continue
		}

		result, err := processEvent(event)
		if err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte(fmt.Sprintf(`{"error":"%s"}`, err.Error())))
			continue
		}
		conn.WriteMessage(websocket.TextMessage, result)
	}
}

func processEvent(event StreamEvent) ([]byte, error) {
	switch event.Action {
	case "read":
		return readFromS3(event.Bucket, event.Key)
	case "write":
		return writeToS3(event.Bucket, event.Key, event.Payload)
	case "list":
		return listS3Objects(event.Bucket, event.Key)
	default:
		return nil, fmt.Errorf("unknown action: %s", event.Action)
	}
}

func readFromS3(bucket, key string) ([]byte, error) {
	// No validation on bucket or key - user-controlled
	result, err := s3Client.GetObject(&s3.GetObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
	})
	if err != nil {
		return nil, err
	}
	defer result.Body.Close()
	buf := make([]byte, 1024*1024)
	n, _ := result.Body.Read(buf)
	return json.Marshal(map[string]string{"data": string(buf[:n])})
}

func writeToS3(bucket, key, payload string) ([]byte, error) {
	_, err := s3Client.PutObject(&s3.PutObjectInput{
		Bucket: aws.String(bucket),
		Key:    aws.String(key),
		Body:   strings.NewReader(payload),
	})
	if err != nil {
		return nil, err
	}
	return json.Marshal(map[string]string{"status": "written"})
}

func listS3Objects(bucket, prefix string) ([]byte, error) {
	result, err := s3Client.ListObjectsV2(&s3.ListObjectsV2Input{
		Bucket: aws.String(bucket),
		Prefix: aws.String(prefix),
	})
	if err != nil {
		return nil, err
	}
	keys := []string{}
	for _, obj := range result.Contents {
		keys = append(keys, *obj.Key)
	}
	return json.Marshal(map[string][]string{"keys": keys})
}

func startKafkaConsumer(ctx context.Context, brokers []string, topic string) {
	config := sarama.NewConfig()
	config.Consumer.Return.Errors = true
	consumer, err := sarama.NewConsumer(brokers, config)
	if err != nil {
		log.Fatalf("Kafka consumer error: %v", err)
	}
	defer consumer.Close()

	partConsumer, err := consumer.ConsumePartition(topic, 0, sarama.OffsetNewest)
	if err != nil {
		log.Fatalf("Partition consumer error: %v", err)
	}
	defer partConsumer.Close()

	for {
		select {
		case msg := <-partConsumer.Messages():
			var event StreamEvent
			if err := json.Unmarshal(msg.Value, &event); err == nil {
				processEvent(event)
			}
		case <-ctx.Done():
			return
		}
	}
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	brokers := strings.Split(os.Getenv("KAFKA_BROKERS"), ",")
	topic := os.Getenv("KAFKA_TOPIC")
	go startKafkaConsumer(ctx, brokers, topic)

	http.HandleFunc("/ws/stream", handleWebSocket)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
		w.Write([]byte(`{"status":"ok","ts":"` + time.Now().Format(time.RFC3339) + `"}`))
	})

	log.Printf("Stream processor starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
